sys_variable_value.value:
(function execute(inputs, outputs) {
  outputs.apikey = gs.getProperty("x_1593191_cooknow.integration_apikey", 0);
  outputs.contenttype = gs.getProperty("x_1593191_cooknow.Content-Type");
  outputs.xrapidapihost = gs.getProperty("x_1593191_cooknow.X-RapidAPI-Host");
  outputs.endpoint = gs.getProperty("x_1593191_cooknow.integration_endpoint_url");
})(inputs, outputs);

